action.transformation:
(

/* set form data */
$components.MainGroupForm.fn.setValue("name",$$.name);
$components.MainGroupForm.fn.setValue("id",$$.mutation.id);

/* set eventlist table to load (should be empty as it is new eventgroup) */
$components.EventListTable.fn.loadData({
  "filter": {
    "eventGroupId": {
      "_eq": $$.mutation.id
    }
  }

});

/* reload eventgroup table */
$components.EventGroupTable.fn.search()

)

transforms.pre:
{
