message.__transform:
(

$q :=  $query({
    "api": "application",
      "statement":"query EventLists{eventList(where: {eventGroupId: {_eq:\"" & rowData.id & "\"}}) { total\n }}"
    });


$q.eventList.total > 0 

? rowData.name & " is configured with " & $q.eventList.total & " events. Are you sure you would like to proceed?"
: "Are you sure you would like to delete event group " & rowData.name & "?"
)

transforms.pre:
(

$q :=  $query({
    "api": "application",
      "statement":"query EventList{eventList(where: {eventGroupId: {_eq:\"" & rowData.id & "\"}}) { total\n edges{\n node{\n id} }}}"
    });


$eventListOrEmpty :=  $q.eventList.total > 0 ? $q.eventList.edges.{
    "where": {
      "id": $.node.id
    }
  } : [];
{ 
  "payloadEventList": $eventListOrEmpty,
  "payloadEventGroup": {
    "where": {
      "id": rowData.id
    }
  }
}
)

